package com.akshay.stockflow.auth;
import jakarta.validation.Valid; import jakarta.validation.constraints.*; import org.springframework.http.HttpStatus; import org.springframework.security.authentication.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.util.Map;
@RestController @RequestMapping("/api/auth") public class AuthController {
private final UserAccountRepository users; private final PasswordEncoder passwords; private final AuthenticationManager authentication; private final JwtService jwt;
public AuthController(UserAccountRepository users,PasswordEncoder passwords,AuthenticationManager authentication,JwtService jwt){this.users=users;this.passwords=passwords;this.authentication=authentication;this.jwt=jwt;}
@PostMapping("/register") @ResponseStatus(HttpStatus.CREATED) public Map<String,Object> register(@Valid @RequestBody RegisterInput input){if(users.existsByEmailIgnoreCase(input.email()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Email is already registered");UserAccount user=users.save(new UserAccount(input.email(),passwords.encode(input.password()),input.fullName(),Role.EMPLOYEE));return Map.of("id",user.getId(),"email",user.getEmail(),"fullName",user.getFullName(),"role",user.getRole());}
@PostMapping("/login") public Map<String,Object> login(@Valid @RequestBody LoginInput input){try{authentication.authenticate(new UsernamePasswordAuthenticationToken(input.email(),input.password()));}catch(org.springframework.security.core.AuthenticationException ex){throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid credentials");}UserAccount user=users.findByEmailIgnoreCase(input.email()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Invalid credentials"));return Map.of("accessToken",jwt.generate(user),"tokenType","Bearer","expiresInSeconds",jwt.expirationSeconds(),"user",Map.of("id",user.getId(),"email",user.getEmail(),"fullName",user.getFullName(),"role",user.getRole()));}
public record RegisterInput(@Email @NotBlank String email,@NotBlank @Size(min=10,max=100) String password,@NotBlank @Size(max=100) String fullName){} public record LoginInput(@Email @NotBlank String email,@NotBlank String password){}
}
